import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    first_map = []
    for _ in range(N):
        first_map.append(next(iterator))

    second_map_rows = []
    for _ in range(M):
        second_map_rows.append(next(iterator))

    for r in range(N - M + 1):
        candidate_block = first_map[r:r+M]
        block_string = ''.join(candidate_block)

        for c in range(N - M + 1):
            match = True
            for k in range(M):
                if candidate_block[k] != second_map_rows[k][c:c+M]:
                    match = False
                    break

            if match:
                print(f"{r + 1} {c + 1}")
                return

if __name__ == "__main__":
    main()
